    var dot_index := file_name.IndexOf('.');
    // Check if there is exactly one dot
    if dot_index < 0 || file_name.IndexOf('.', dot_index + 1) >= 0 {
        return false;
    }

    // Check the substring before the dot
    var name_part := file_name.Substring(0, dot_index);
    if name_part.Length == 0 || !(is_letter(name_part[0])) {
        return false;
    }

    // Check the substring after the dot
    var extension_part := file_name.Substring(dot_index + 1);
    if !(extension_part == "txt" || extension_part == "exe" || extension_part == "dll") {
        return false;
    }

    // Check the number of digits
    var digit_count := 0;
    for i := 0 to name_part.Length - 1 {
        if name_part[i] >= '0' && name_part[i] <= '9' {
            digit_count := digit_count + 1;
        }
    }
    return digit_count <= 3;
}

function is_letter(c: char) : bool
